// Order: duplicate -> suppression (smc_hash_contact, digits only) -> WHATSAPP_TEST_RECIPIENTS -> template approval /
// 24-h window -> DRY_RUN_SENDS (external_id dry:<correlation>) -> send.
const L = require('lv-automation').subWhatsappSend;
const n = $('Normalise input').item.json;
return { json: L.decide(n, $json, $env, Date.now()) };

const P = require('lv-automation').waProvider;
const d = $('Decide (suppression, allow-list, window, template, dry run)').item.json;
const cb = $env.WEBHOOK_URL ? String($env.WEBHOOK_URL).replace(/\/$/, '') + '/webhook/whatsapp-twilio' : undefined;
const r = P.toTwilioRequest(d.payload, $env, { statusCallback: cb });
if (r.skip) return { json: { twilio_skip: r.reason, email_fallback: /content_sid_missing/.test(r.reason) } };
const body = new URLSearchParams(r.form).toString();
const auth = 'Basic ' + Buffer.from($env.TWILIO_API_KEY_SID + ':' + $env.TWILIO_API_KEY_SECRET).toString('base64');
return { json: { body, auth, via: r.via || 'native' } };

const L = require('lv-automation').subWhatsappSend;
// Both providers land here (name kept for callers/tests): Graph { messages[0].id } or Twilio { sid } / { twilio_skip }.
return { json: L.interpret($json) };

// I-47g: W22 producer contract (automation/W22.md section 3), handed over by Execute Workflow smc-w22.
const d = $('Decide (suppression, allow-list, window, template, dry run)').item.json;
const r = $('Interpret Graph response').item.json;
return { json: { signal_key: 'whatsapp_send_failed', scope: d.broker_id ? 'broker:' + d.broker_id : 'lead:' + d.lead_id, severity: 'amber', what: 'WhatsApp send failed (' + (d.template || d.sent_as) + '): ' + (r.error || 'non-2xx'), impact: 'A broker or ops message was not delivered', first_action: 'Check the template status and the Graph error in the execution', source: 'smc-whatsapp-send' } };

// { ok, external_id, error } (callers do not wait today; kept for a waiting caller).
const L = require('lv-automation').subWhatsappSend;
const d = $('Decide (suppression, allow-list, window, template, dry run)').item.json;
let r = null; try { r = $('Interpret Graph response').item.json; } catch (e) { r = null; }
return { json: L.result(d, r) };
